"""One-shot seed script: populate 1 representative entry per BRD topic.

For each topic in BRD_TOPICS (+ 8 role leaves), writes:
  - markdown body at  ../YiKnowledge/brd/<topic>/<key>.md
  - metadata doc    in Mongo collection brd_<topic>

Idempotent: if a collection already has ≥1 doc, that topic is skipped.

Run from YiAi/ (so ../YiKnowledge resolves correctly):
    python scripts/seed_brd_topics.py
"""
from __future__ import annotations

import asyncio
import sys
import time
import random
from pathlib import Path

# Make src/ importable
ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "src"))

from data.database import db  # type: ignore
from domain.knowledge.writer import write_entry_markdown  # type: ignore


def _key(topic: str) -> str:
    stamp = int(time.time() * 1000)
    rand = random.randint(10_000, 99_999)
    return f"brd_{topic}_{stamp}{rand}"


def _md(topic: str, label: str, content: str) -> str:
    return (
        f"# {label} — Reference Seed\n\n"
        f"> Curated reference entry for the **{label}** topic. "
        f"Use it as a starting point; replace with project-specific content as the BRD evolves.\n\n"
        f"## Summary\n\n{content}\n\n"
        f"## Fields to Fill\n\n"
        f"- Owner / reviewer / stakeholders\n"
        f"- Status (draft → in_progress → reviewed → adopted)\n"
        f"- Tags relevant to your project\n"
        f"- Topic-specific structured `meta` fields\n\n"
        f"---\n*Seed entry generated by `scripts/seed_brd_topics.py`.*\n"
    )


