async def _collection_has_any(cname: str) -> bool:
    existing = await db.find_one(cname, {})
    return existing is not None


async def _seed_one(topic: str, label: str, content: str) -> str:
    cname = f"brd_{topic}"
    if await _collection_has_any(cname):
        return f"skip   {topic:<40} (already has entries)"

    key = _key(topic)
    rel_path = f"brd/{topic}/{key}.md"
    now_ms = int(time.time() * 1000)

    # 1) markdown body under YiKnowledge/brd/<topic>/
    write_entry_markdown(rel_path, _md(topic, label, content), {
        "title": f"{label}",
        "key": key,
        "topic": topic,
        "tags": ["seed", "reference"],
        "status": "draft",
    })

    # 2) metadata doc in Mongo collection brd_<topic>
    doc = {
        "key": key,
        "topic": topic,
        "title": f"{label}",
        "tags": ["seed", "reference"],
        "meta": {"status": "draft", "category": "Seed"},
        "contentPath": rel_path,
        "content": "",
        "createdAt": now_ms,
        "updatedAt": now_ms,
    }
    await db.insert_one(cname, doc)
    return f"wrote  {topic:<40} -> {rel_path}"


async def main() -> int:
    await db.initialize()
    written = 0
    skipped = 0
    failed = 0
    for topic, label, content in TOPICS:
        try:
            msg = await _seed_one(topic, label, content)
            print(msg)
            if msg.startswith("wrote"):
                written += 1
            else:
                skipped += 1
        except Exception as e:  # noqa: BLE001
            print(f"FAIL   {topic:<40} -> {e}")
            failed += 1
    print(f"\nDone. wrote={written} skip={skipped} fail={failed} total={len(TOPICS)}")
    await db.close()
    return 0 if failed == 0 else 1


if __name__ == "__main__":
    raise SystemExit(asyncio.run(main()))
